from collections import deque
calls = {  # 호출하는 쪽 -> 호출받는 쪽
    "app-gateway": ["auth", "route", "search"],
    "route": ["traffic", "map-tile"],
    "search": ["poi"],
    "drive-score": ["auth", "dynamo"],
    "ad": ["poi"],
}
callers = {}
for src, dsts in calls.items():
    for d in dsts:
        callers.setdefault(d, []).append(src)
def impacted(down):
    seen, q = set(), deque([down])
    while q:
        for c in callers.get(q.popleft(), []):
            if c not in seen:
                seen.add(c); q.append(c)
    return sorted(seen)
print("poi 가 죽으면:", impacted("poi"))
print("auth 가 죽으면:", impacted("auth"))
# poi 가 죽으면: ['ad', 'app-gateway', 'search']
# auth 가 죽으면: ['app-gateway', 'drive-score']
